sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({ api, helpers }) {
  // Fetch the stages from the API response
  const stages = api.data.breadcrumb_1.output || [];
  console.log('stagesssfdfddddddddd', stages);

  // Make sure stages data is available and not empty
  if (stages.length === 0) {
    return `<div>No stages data available.</div>`;
  }

  // Function to dynamically assign classes
  const getStepClass = (index, total, stageName) => {
    if (stageName === "Validate Software  Model") return "persona-stage"; // Apply special class for "Persona"
    if (index === 0) return "start"; // First step is "start"
    if (index === total - 1) return "current"; // Last step is "current"
    return "mid"; // Other steps are "mid"
  };

  let stepsHtml = "";

  // Iterate over stages using forEach
  stages.forEach((stage, index) => {
    const trimmedStage = stage?.name?.trim() || `Unnamed Stage ${index + 1}`;
    console.log("Trimmed Stage:", trimmedStage);
    const stepClass = getStepClass(index, stages.length, trimmedStage);

    stepsHtml += `
      <li class="${stepClass}">
        <a style="font-weight: bold;">${trimmedStage}</a>
      </li>
    `;
  });

  return `
    <style>
      .stepcontainer {
        display: flex;
        justify-content: center;
        width: 100%;
        margin: 0 auto;
        padding: 0;
        box-sizing: border-box;
      }

      .steps {
        display: flex;
        padding: 0;
        width: 100%;
        overflow: hidden;
        color: white !important;
      }

      .steps li {
        flex: 1;
        height: 26px;
        width: 50px;
        list-style-type: none;
        padding: 5px 0;
        position: relative;
        box-sizing: border-box;
        text-align: center;
        display: flex;
        justify-content: center;
        align-items: center;
      }

      .steps li:first-child {
        padding-left: 5px;
      }

      .steps li:nth-child(n + 2)::before {
        position: absolute;
        top: 0;
        left: 0;
        display: block;
        border-left: 10px solid white;
        border-top: 15px solid transparent;
        border-bottom: 16px solid transparent;
        width: 0;
        height: 0;
        content: " ";
      }

      .steps li::after {
        z-index: 1;
        position: absolute;
        top: 0;
        right: -9px;
        display: block;
        border-left: 10px solid #84e78c;
        border-top: 15px solid transparent;
        border-bottom: 14px solid transparent;
        width: 0;
        height: 0;
        content: " ";
      }

      .steps li.start {
        background-color: #4F52BD;
      }

      .steps li.start::after {
        border-left-color: #4F52BD;
      }

      .steps li.mid {
        background-color: #4F52BD;
        border-left: 3px solid white;
      }

      .steps li.mid::after {
        border-left-color: #4F52BD;
      }

      .steps li.current {
        background-color: #4F52BD;
        border-left: 3px solid white;
      }

      .steps li.current::after {
        border-left-color: #ebebe0;
      }

      /* Special styling for Persona stage */
      .steps li.persona-stage {
        background-color: #009900 !important;
        border-left: 3px solid white;
      }

      .steps li.persona-stage::after {
        border-left-color: #009900 !important;
      }

      .steps li a {
        font-size: 10px;
        color: inherit;
        text-decoration: none;
        display: block;
        width: 100%;
        height: 100%;
        text-align: center;
        line-height: 70px;
        display: flex;
        justify-content: center;
        align-items: center;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
      }
    </style>

    <div class="stepcontainer">
      <ul class="steps">
         ${stepsHtml}
      </ul>
    </div>
  `;
}
